// lemlist on an API key: every operation of lemlist's public API (campaigns, leads, sequences, contacts, companies,
// inbox, tasks, enrichment, unsubscribes, warmup, signals...). actions.json is generated by
// `bun scripts/openapi-actions.ts lemlist`; every lemlist event (opens, replies, clicks, bounces, LinkedIn, WhatsApp,
// SMS, calls, unsubscribes...) starts automations by webhook (triggers.ts), new campaigns and companies by polling.
import type { OwnApp } from "../index";
import { type Api, call, specActions } from "../openapi";
import { events, receive, triggers, unwatch, wanted, watch } from "./triggers";

export const api: Api = {
  name: "lemlist",
  base: "https://api.lemlist.com/api",
  tokenHelp: "lemlist → Settings → Integrations → API",
  // basic auth with an empty login and the key as the password
  auth: (key) => ({ Authorization: `Basic ${Buffer.from(`:${key}`).toString("base64")}` }),
};

const TEAM = { method: "GET", path: "/team", query: [], headers: [] };

export const lemlist: OwnApp = {
  app: "lemlist",
  name: "lemlist",
  logo: "/logos/lemlist.svg",
  keyField: {
    label: "API key",
    help: "In lemlist, open Settings → Integrations, find API and click Generate (or copy your existing key). Emplio can then see and change whatever your lemlist user can. To let Emplio start automations from replies, opens and other events, your user also needs the \"Edit integrations\" permission.",
    placeholder: "1a2b3c4d5e6f...",
  },
  async check(key) {
    const team = (await call(api, key, TEAM, {})) as { name?: string };
    return team.name || "lemlist";
  },
  push: {
    events,
    triggers,
    start: (key, connection) => watch(api, key, connection),
    stop: (key, id) => unwatch(api, key, id),
    receive,
    wanted,
  },
  actions: await specActions(new URL("./actions.json", import.meta.url), api),
};
